import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr03203Controller {
  @Post('/attendance-dailies/:attendanceDailyId/agree')
  @HttpCode(200)
  async agreeAttendanceDaily(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const id = req.params['attendanceDailyId'];
    if (typeof data['employeeAgreed'] !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '근무시간 동의 여부를 입력하세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT employee_id AS "employeeId", closing_status AS "closingStatus" FROM attendance_daily WHERE attendance_daily_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_DAILY_NOT_FOUND', '대상 근태 기록이 없습니다.');
      }
      if (String(rows[0].employeeId) !== String(user.id)) {
        throw new ApiError(403, 'FORBIDDEN', '본인의 근무시간에만 동의할 수 있습니다.');
      }
      if (rows[0].closingStatus === '승인') {
        throw new ApiError(409, 'ATTENDANCE_ALREADY_APPROVED', '이미 승인된 근무시간입니다. 승인취소 절차를 먼저 진행하세요.');
      }
      const out = await db.query(
        'UPDATE attendance_daily SET employee_agreed = :agreed, agreed_at = now(), updated_at = now() WHERE attendance_daily_id = CAST(:id AS bigint) RETURNING attendance_daily_id AS "attendanceDailyId", employee_agreed AS "employeeAgreed", closing_status AS "closingStatus"',
        { id, agreed: data['employeeAgreed'] },
      );
      return out[0];
    });
  }

  @Post('/attendance-dailies/:attendanceDailyId/approve')
  @HttpCode(200)
  async approveAttendanceDaily(@Req() req: Request) {
    const user = currentUser(req);
    user.require('근태 담당자');
    const data = checks.inputOf(req.body);
    const id = req.params['attendanceDailyId'];
    if (typeof data['approved'] !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 또는 반려를 선택하세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT employee_agreed AS "employeeAgreed", closing_status AS "closingStatus" FROM attendance_daily WHERE attendance_daily_id = CAST(:id AS bigint)',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'ATTENDANCE_DAILY_NOT_FOUND', '대상 근태 기록이 없습니다.');
      }
      if (rows[0].closingStatus === '승인') {
        throw new ApiError(409, 'ATTENDANCE_ALREADY_APPROVED', '이미 승인된 근무시간입니다. 승인취소 절차를 먼저 진행하세요.');
      }
      if (rows[0].employeeAgreed !== true) {
        throw new ApiError(422, 'EMPLOYEE_NOT_AGREED', '임직원이 근무시간에 동의하지 않았습니다.');
      }
      if (data['approved'] === true) {
        const out = await db.query(
          "UPDATE attendance_daily SET closing_status = '승인', approver_id = CAST(:userId AS bigint), approved_at = now(), updated_at = now() WHERE attendance_daily_id = CAST(:id AS bigint) RETURNING attendance_daily_id AS \"attendanceDailyId\", closing_status AS \"closingStatus\"",
          { id, userId: user.id },
        );
        return out[0];
      }
      // 가정: 반려는 스키마에 반려 상태가 없어 신청 상태로 되돌리고 동의를 비운다.
      const out = await db.query(
        "UPDATE attendance_daily SET closing_status = '신청', employee_agreed = NULL, agreed_at = NULL, updated_at = now() WHERE attendance_daily_id = CAST(:id AS bigint) RETURNING attendance_daily_id AS \"attendanceDailyId\", closing_status AS \"closingStatus\"",
        { id },
      );
      return out[0];
    });
  }
}

