import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager,
  Drawer, Form, Field, DateInput, Select, RefName, Tiles, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr03203Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [applied, setApplied] = useState({ startDate: '', endDate: '' });
  const [page, setPage] = useState(0);
  const [agreeRow, setAgreeRow] = useState<Row | null>(null);
  const [approveRow, setApproveRow] = useState<Row | null>(null);
  const [agreeValue, setAgreeValue] = useState('');
  const [approveValue, setApproveValue] = useState('');

  const { data, error, reload } = useData<Page>(async () => {
    if (!applied.startDate || !applied.endDate) {
      return { items: [], page: 0, size: 20, total: 0 };
    }
    return call<Page>('GET', '/attendance-dailies', role, undefined, {
      startDate: applied.startDate,
      endDate: applied.endDate,
      page,
      size: 20,
    });
  }, [applied, page, role]);

  const rows = data?.items ?? [];
  const waiting = rows.filter((r) => r['closingStatus'] !== '승인');

  const search = () => {
    setPage(0);
    setApplied({ startDate, endDate });
  };

  const reset = () => {
    setStartDate('');
    setEndDate('');
    setPage(0);
    setApplied({ startDate: '', endDate: '' });
  };

  const submitAgree = async () => {
    if (!agreeValue) {
      throw new Error('동의 여부를 선택하세요.');
    }
    await call(
      'POST',
      '/attendance-dailies/{attendanceDailyId}/agree'.replace('{attendanceDailyId}', String(agreeRow?.['attendanceDailyId'])),
      role,
      { employeeAgreed: agreeValue === 'true' },
    );
    notify('근무시간 동의를 처리했습니다.');
    setAgreeRow(null);
    setAgreeValue('');
    reload();
  };

  const submitApprove = async () => {
    if (!approveValue) {
      throw new Error('승인 또는 반려를 선택하세요.');
    }
    await call(
      'POST',
      '/attendance-dailies/{attendanceDailyId}/approve'.replace('{attendanceDailyId}', String(approveRow?.['attendanceDailyId'])),
      role,
      { approved: approveValue === 'true' },
    );
    notify('근무시간 승인 처리를 했습니다.');
    setApproveRow(null);
    setApproveValue('');
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>근태 현황</h2>
        <Tiles
          items={[
            ['조회 건수', data?.total ?? 0],
            ['처리 대기', waiting.length],
            ['승인 완료', rows.length - waiting.length],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>일별 근태</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total ?? 0} />
        <DataTable
          rows={rows}
          empty="조회 기간을 입력하고 조회하세요."
          columns={[
            {
              key: 'employeeId',
              label: '임직원',
              render: (r) => <RefName table="employee" role={role} value={r['employeeId']} />,
            },
            { key: 'workDate', label: '근무일자', render: (r) => <DateText value={r['workDate']} /> },
            { key: 'clockInAt', label: '출근시각', render: (r) => <DateText value={r['clockInAt']} time /> },
            { key: 'clockOutAt', label: '퇴근시각', render: (r) => <DateText value={r['clockOutAt']} time /> },
            { key: 'sourceType', label: '기록 출처' },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r['closingStatus']} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) =>
                r['closingStatus'] === '승인' ? null : (
                  <span>
                    <button type="button" onClick={(e) => { e.stopPropagation(); setAgreeValue(''); setAgreeRow(r); }}>
                      동의
                    </button>
                    <button type="button" onClick={(e) => { e.stopPropagation(); setApproveValue(''); setApproveRow(r); }}>
                      승인·반려
                    </button>
                  </span>
                ),
            },
          ]}
        />
        <Pager page={page} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          rows={waiting}
          empty="대기 건이 없습니다."
          columns={[
            { key: 'workDate', label: '근무일자', render: (r) => <DateText value={r['workDate']} /> },
            { key: 'closingStatus', label: '상태', render: (r) => <Badge value={r['closingStatus']} /> },
          ]}
        />
      </section>
      {agreeRow ? (
        <Drawer title="근무시간 동의" onClose={() => setAgreeRow(null)}>
          <Form onSubmit={submitAgree} submit="동의 처리">
            <Field label="근무시간 동의 여부" required>
              <Select
                value={agreeValue}
                onChange={setAgreeValue}
                options={[['true', '동의'], ['false', '동의하지 않음']]}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}
      {approveRow ? (
        <Drawer title="근무시간 승인·반려" onClose={() => setApproveRow(null)}>
          <Form onSubmit={submitApprove} submit="처리">
            <Field label="승인(true) 또는 반려(false)" required>
              <Select
                value={approveValue}
                onChange={setApproveValue}
                options={[['true', '승인'], ['false', '반려']]}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
